// ─── File: HierarchyDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.exc;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class HierarchyDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"));
        PaymentService service = new PaymentService();

        // CHECKED: compiler forced this try-catch to exist.
        try {
            service.settle(priya, new BigDecimal("999999"));
        } catch (BankException e) {
            // Common Throwable machinery: message + cause chain.
            log.severe(() -> "Checked caught: " + e.getMessage()
                    + " | cause=" + (e.getCause() == null ? "none" : e.getCause().getMessage()));
        }

        // UNCHECKED: no compiler obligation, but we still choose to catch.
        try {
            service.validate(rajesh, new BigDecimal("-5000"));
        } catch (InvalidAmountException e) {
            log.severe(() -> "Unchecked caught: " + e.getMessage());
        }

        // ERROR is NOT caught here on purpose — it should propagate and crash.
        log.info(() -> "Demo finished; Error types are deliberately not caught.");
    }
}

// ─── Would be in BankException.java (CHECKED) ───
class BankException extends Exception {           // extends Exception → checked
    BankException(String message) { super(message); }
    BankException(String message, Throwable cause) { super(message, cause); }
}

// ─── Would be in InvalidAmountException.java (UNCHECKED) ───
class InvalidAmountException extends RuntimeException { // extends RuntimeException → unchecked
    InvalidAmountException(String message) { super(message); }
}

// ─── Would be in Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in PaymentService.java ───
class PaymentService {
    // Checked method: declares throws, forcing callers to handle it.
    void settle(Account from, BigDecimal amount) throws BankException {
        if (from.getBalance().compareTo(amount) < 0) {
            // Wrap a simulated low-level cause to show the cause chain.
            Throwable lowLevel = new IllegalStateException("ledger rejected debit");
            throw new BankException("Settlement failed for " + from.getHolderName(), lowLevel);
        }
        from.debit(amount);
    }

    // Unchecked method: no throws clause needed.
    void validate(Account acc, BigDecimal amount) {
        if (amount.signum() <= 0) {
            throw new InvalidAmountException("Amount must be positive, got " + amount);
        }
    }
}
